package com.gameaggregator.featureflagservice.api;import jakarta.validation.constraints.*;import java.util.*;import java.util.UUID;public final class FeatureFlagDtos{private FeatureFlagDtos(){}public record Create(@Pattern(regexp="[a-z0-9._-]+")String key,@NotBlank String description,boolean enabled,@Min(0)@Max(100)int rolloutPercentage,Set<UUID> clientTargets,@NotNull UUID actorId){}public record Update(@NotBlank String description,boolean enabled,boolean killSwitch,@Min(0)@Max(100)int rolloutPercentage,Set<UUID> clientTargets,@NotNull UUID actorId){}public record OverrideRequest(@Pattern(regexp="TENANT|ENVIRONMENT")String scopeType,@NotNull UUID scopeId,boolean enabled,@Min(0)@Max(100)int rolloutPercentage,@NotNull UUID actorId){}public record Evaluation(String key,boolean enabled,String reason){} }